<script setup lang="ts">
import { AlertCircle, CheckCircle2, Clock3, Headphones, MessageSquare, Plus, RefreshCw, Search, Send, Users, X } from '@lucide/vue';
import { requestKey } from '~/shared/request-key';
const config = useRuntimeConfig();
const route = useRoute();
const props = defineProps<{ pageSection?: string }>();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const access = useWorkspaceAccess();
const canCreate = computed(() => access.can('helpdesk.write'));
const canWriteTicket = (ticket: any) => canCreate.value && ticket?.canWrite === true;
const dashboard = ref<any>(null);
const tickets = ref<any[]>([]);
const agents = ref<any[]>([]);
const selected = ref<any>(null);
const createOpen = ref(false);
const loading = ref(false);
const loaded = ref(false), listPage = ref(1);
const pageSize = 25;
const error = ref('');
const notice = ref('');
const search = ref('');
const statusFilter = ref('');
const sourceFilter = ref('');
const comment = ref('');
const internalComment = ref(false);
const sendEmail = ref(false);
let pendingReply: { key: string; signature: string } | null = null;
watch(internalComment, value => { if (value) sendEmail.value = false; });
const deliveryLabel = (status: string) => ({ QUEUED: 'Email ожидает отправки', PROCESSING: 'Email отправляется', SENT: 'Email отправлен', FAILED: 'Email не отправлен', CANCELLED: 'Отправка email отменена' }[status] || 'Состояние email уточняется');
const actionBusy = ref(false);
const createPanel = ref<HTMLElement | null>(null), detailPanel = ref<HTMLElement | null>(null);
const filtersActive = computed(() => Boolean(search.value || statusFilter.value || sourceFilter.value || queueFilter.value));
let returnFocus: HTMLElement | null = null, previousOverflow: string | null = null;
const dialogOpen = computed(() => createOpen.value || Boolean(selected.value));
function unlockDialog() { if (previousOverflow === null) return; document.documentElement.style.overflow = previousOverflow; previousOverflow = null; }
function dialogKeys(event: KeyboardEvent) {
  if (event.key === 'Escape') { event.preventDefault(); if (actionBusy.value) return; if (createOpen.value) closeCreate(); else closeTicket(); return; }
  if (event.key !== 'Tab') return;
  const panel = createOpen.value ? createPanel.value : detailPanel.value;
  const controls = [...(panel?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), textarea:not(:disabled), select:not(:disabled), a[href]') || [])].filter(el => el.getClientRects().length);
  const first = controls[0], last = controls[controls.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
}
watch(dialogOpen, async open => {
  if (!import.meta.client) return;
  if (open) { returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; if (previousOverflow === null) previousOverflow = document.documentElement.style.overflow; document.documentElement.style.overflow = 'hidden'; await nextTick(); const panel = createOpen.value ? createPanel.value : detailPanel.value; (panel?.querySelector<HTMLElement>('input:not(:disabled),select:not(:disabled),textarea:not(:disabled)') || panel?.querySelector<HTMLElement>('button:not(:disabled)'))?.focus(); }
  else { unlockDialog(); await nextTick(); if (returnFocus?.isConnected) returnFocus.focus(); }
});
onBeforeUnmount(unlockDialog);
const queueFilter = computed(() => typeof route.query.queue === 'string' ? route.query.queue : '');
const section = computed(() => props.pageSection || String(route.query.section || 'overview'));
let loadVersion = 0;
let loadController: AbortController | undefined;
const form = reactive({ subject:'', description:'', source:'EMPLOYEE', priority:'MEDIUM', affectedService:'Workspace' });
const createDirty = computed(() => Boolean(form.subject.trim() || form.description.trim()));
function closeCreate() { if (!actionBusy.value && (!createDirty.value || window.confirm('Закрыть без создания заявки?'))) createOpen.value = false; }
const statusLabels:Record<string,string> = { NEW:'Новая',OPEN:'В работе',WAITING_REQUESTER:'Ждём заявителя',WAITING_INTERNAL:'Внутреннее ожидание',RESOLVED:'Решена',CLOSED:'Закрыта' };
const priorityLabels:Record<string,string> = { LOW:'Низкий',MEDIUM:'Обычный',HIGH:'Высокий',CRITICAL:'Критический' };
const sourceLabels:Record<string,string> = { EMPLOYEE:'Сотрудник',B2C:'Клиент B2C',B2B:'Клиент B2B',SYSTEM:'Система' };
const filtered = computed(() => tickets.value.filter(ticket => (!queueFilter.value || (ticket.queue || 'Первая линия') === queueFilter.value) && (!statusFilter.value || ticket.status === statusFilter.value) && (!sourceFilter.value || ticket.source === sourceFilter.value) && (!search.value || `${ticket.number} ${ticket.subject} ${ticket.requesterEmail || ''}`.toLowerCase().includes(search.value.toLowerCase()))));
const listPages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize)));
const visibleTickets = computed(() => filtered.value.slice((listPage.value - 1) * pageSize, listPage.value * pageSize));
watch([search, statusFilter, sourceFilter, queueFilter], () => { listPage.value = 1; });
watch(listPages, value => { if (listPage.value > value) listPage.value = value; });
const attentionTickets = computed(() => tickets.value.filter(ticket => !['RESOLVED','CLOSED'].includes(ticket.status)).slice(0,6));
const queues = computed(() => Array.from(new Set(tickets.value.map(ticket => ticket.queue || 'Первая линия'))).map(queue => ({ name:queue, total:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue).length, open:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue && !['RESOLVED','CLOSED'].includes(ticket.status)).length })));
const slaState = (ticket:any) => ticket.resolutionDueAt && new Date(ticket.resolutionDueAt) < new Date() && !['RESOLVED','CLOSED'].includes(ticket.status) ? 'Просрочена' : 'В срок';
function requester(ticket:any) { return [ticket.requesterUser?.firstName,ticket.requesterUser?.lastName].filter(Boolean).join(' ') || ticket.requesterName || ticket.requesterEmail || sourceLabels[ticket.source]; }
async function load() {
  if (section.value === 'knowledge') return;
  if (!token.value || section.value === 'knowledge') return;
  const version = ++loadVersion, identity = token.value;
  loadController?.abort(); const controller = new AbortController(); loadController = controller;
  loading.value = true; error.value = '';
  try {
    const options = { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${identity}` }, signal: controller.signal, timeout: 20000 };
    const [nextDashboard, nextTickets, nextAgents] = await Promise.all([
      section.value === 'overview' ? $fetch('/helpdesk/dashboard', options) : Promise.resolve(null),
      $fetch<any[]>('/helpdesk/tickets', options),
      section.value === 'tickets' ? $fetch<any[]>('/helpdesk/agents', options) : Promise.resolve(null),
    ]);
    if (version !== loadVersion || token.value !== identity) return;
    if (nextDashboard) dashboard.value = nextDashboard;
    tickets.value = nextTickets;
    loaded.value = true;
    if (nextAgents) agents.value = nextAgents;
    if (selected.value) selected.value = tickets.value.find(ticket => ticket.id === selected.value.id) || null;
  } catch (e: any) { if (version === loadVersion && token.value === identity && !controller.signal.aborted) error.value = typeof e?.data?.message === 'string' ? e.data.message : 'Не удалось загрузить поддержку. Повторите попытку.'; }
  finally { if (version === loadVersion) loading.value = false; }
}
onUnmounted(() => { ++loadVersion; loadController?.abort(); });
function fail(e:any) { error.value = Array.isArray(e?.data?.message) ? e.data.message.join(', ') : e?.data?.message || 'Действие не выполнено. Повторите попытку.'; }
async function createTicket(){
  if(actionBusy.value || !canCreate.value)return; actionBusy.value=true; error.value='';
  try{await $fetch('/helpdesk/tickets',{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:{...form}});Object.assign(form,{subject:'',description:'',source:'EMPLOYEE',priority:'MEDIUM',affectedService:'Workspace'});createOpen.value=false;notice.value='Заявка создана';await load();setTimeout(()=>notice.value='',2200);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
async function updateTicket(ticket:any, field:string, value:string|null){
  if(actionBusy.value || !canWriteTicket(ticket))return; actionBusy.value=true; error.value='';
  try{const updated=await $fetch<any>(`/helpdesk/tickets/${ticket.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:{Authorization:`Bearer ${token.value}`},body:{[field]:field==='assignedToId' ? value || null : value}});Object.assign(ticket,updated);notice.value='Заявка обновлена';setTimeout(()=>notice.value='',1800);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
async function changeTicket(event:Event,ticket:any,field:string){
  const input=event.target as HTMLInputElement;
  await updateTicket(ticket,field,input.value);
  input.value=ticket[field] || '';
}
async function addComment(){
  if(!comment.value.trim()||!canWriteTicket(selected.value)||actionBusy.value)return;
  const ticket=selected.value; actionBusy.value=true; error.value='';
  try{const body=comment.value.trim(),isInternal=internalComment.value,email=sendEmail.value&&!isInternal;const signature=JSON.stringify([ticket.id,body,isInternal,email]);if(!pendingReply||pendingReply.signature!==signature)pendingReply={key:requestKey(),signature};const created=await $fetch<any>(`/helpdesk/tickets/${ticket.id}/comments`,{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:{body,isInternal,sendEmail:email,requestKey:pendingReply.key}});ticket.comments=[...(ticket.comments||[]).filter((item:any)=>item.id!==created.id),{...created,author:created.author||user.value}];comment.value='';internalComment.value=false;sendEmail.value=false;pendingReply=null;notice.value=email?'Ответ сохранён и поставлен в очередь email':'Комментарий сохранён';setTimeout(()=>notice.value='',2500);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
function closeTicket(){if(actionBusy.value || (comment.value.trim() && !window.confirm('Отменить неотправленный комментарий?')))return false;selected.value=null;comment.value='';internalComment.value=false;sendEmail.value=false;pendingReply=null;return true;}
function openTicket(ticket:any){if(closeTicket()){selected.value=ticket;error.value='';}}
const ticketsPath = computed(() => route.path.startsWith('/crm/') ? '/crm/support/tickets' : '/helpdesk/tickets');
function openQueue(queue:string){const query={...route.query,queue};delete query.section;return navigateTo({path:ticketsPath.value,query});}
function resetFilters(){search.value='';statusFilter.value='';sourceFilter.value='';const query={...route.query};delete query.queue;delete query.section;return navigateTo({path:ticketsPath.value,query});}
onBeforeRouteLeave(() => !actionBusy.value && (!(comment.value.trim() || (createOpen.value && createDirty.value)) || window.confirm('Уйти без сохранения заявки или комментария?')));
function ticketMenu(event:MouseEvent,ticket:any){openContextMenu(event,ticket.number,[{label:'Открыть заявку',icon:'open',action:()=>openTicket(ticket)},{label:'Копировать номер',icon:'copy',action:()=>copyText(ticket.number,'Номер заявки скопирован')},...(canWriteTicket(ticket) && !['OPEN','RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Взять в работу',icon:'status' as const,separator:true,disabled:actionBusy.value,action:()=>updateTicket(ticket,'status','OPEN')}]:[]),...(canWriteTicket(ticket) && !['RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Отметить решённой',icon:'status' as const,disabled:actionBusy.value,action:()=>updateTicket(ticket,'status','RESOLVED')}]:[])],requester(ticket));}
let targetVersion = 0;
async function openRequestedTicket() {
  const id = route.query.ticket, identity = token.value, version = ++targetVersion;
  if (typeof id !== 'string' || !id || !identity) return;
  try {
    const ticket = await $fetch<any>(`/helpdesk/tickets/${encodeURIComponent(id)}`, { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${identity}` } });
    if (version === targetVersion && identity === token.value) openTicket(ticket);
  } catch (e) { if (version === targetVersion && identity === token.value) { if (closeTicket()) fail(e); } }
}
watch(() => route.query.ticket, openRequestedTicket);
onBeforeUnmount(() => { ++targetVersion; });
onMounted(async () => { await load(); await openRequestedTicket(); });
</script>

<template><CrmKnowledgeBase v-if="section === 'knowledge'" /><main v-else data-v-ui-9200e9d7b7db class="helpdesk-page crm-standard crm-management-workspace"><header data-v-ui-9200e9d7b7db class="hd-header crm-page-header"><div data-v-ui-9200e9d7b7db><h1 data-v-ui-9200e9d7b7db>{{ section === 'tickets' ? 'Все заявки' : section === 'queues' ? 'Очереди поддержки' : section === 'knowledge' ? 'База знаний' : 'Центр поддержки' }}</h1><span data-v-ui-9200e9d7b7db>Обращения сотрудников и клиентов, исполнители и сроки решения</span></div><div data-v-ui-9200e9d7b7db><button data-v-ui-9200e9d7b7db class="outline crm-button crm-button--refresh" :disabled="loading || actionBusy" @click="load"><RefreshCw data-v-ui-9200e9d7b7db :size="16" :class="{spin:loading}" /> Обновить</button><button data-v-ui-9200e9d7b7db class="primary crm-button crm-button--primary" :disabled="actionBusy" v-if="canCreate" @click="createOpen=true"><Plus data-v-ui-9200e9d7b7db :size="16" /> Новая заявка</button></div></header><p data-v-ui-9200e9d7b7db v-if="error && loaded" class="operation-error" role="alert">{{ error }}</p><WorkspaceLoading v-if="!loaded && loading" label="Загружаем обращения" /><div data-v-ui-9200e9d7b7db v-else-if="error && !loaded" class="crm-management-error"><AlertCircle data-v-ui-9200e9d7b7db :size="22" /><span data-v-ui-9200e9d7b7db>{{ error }}</span><button class="crm-button" data-v-ui-9200e9d7b7db @click="load">Повторить</button></div><div data-v-ui-9200e9d7b7db v-else class="hd-body crm-page-content">
  <template v-if="section === 'overview'"><section data-v-ui-9200e9d7b7db class="hd-kpis"><article class="crm-surface" data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Новые</span><strong data-v-ui-9200e9d7b7db class="coral">{{ dashboard?.new || 0 }}</strong><small data-v-ui-9200e9d7b7db>ещё не распределены</small></article><article class="crm-surface" data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>В работе</span><strong data-v-ui-9200e9d7b7db>{{ dashboard?.inWork || 0 }}</strong><small data-v-ui-9200e9d7b7db>есть исполнитель</small></article><article class="crm-surface" data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Ожидают</span><strong data-v-ui-9200e9d7b7db>{{ dashboard?.waiting || 0 }}</strong><small data-v-ui-9200e9d7b7db>ответа или действия</small></article><article class="crm-surface" data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Просрочены</span><strong data-v-ui-9200e9d7b7db :class="{'red':dashboard?.overdue}">{{ dashboard?.overdue || 0 }}</strong><small data-v-ui-9200e9d7b7db>нарушен SLA</small></article></section><section data-v-ui-9200e9d7b7db class="hd-grid"><article data-v-ui-9200e9d7b7db class="panel crm-surface"><div data-v-ui-9200e9d7b7db class="panel-head"><div data-v-ui-9200e9d7b7db><h2 data-v-ui-9200e9d7b7db>Требуют внимания</h2></div><NuxtLink data-v-ui-9200e9d7b7db :to="ticketsPath">Все заявки</NuxtLink></div><div data-v-ui-9200e9d7b7db v-for="ticket in attentionTickets" :key="ticket.id" class="ticket-compact" role="button" tabindex="0" @keydown.enter.prevent="openTicket(ticket)" @keydown.space.prevent="openTicket(ticket)" @click="openTicket(ticket)" @contextmenu.prevent="ticketMenu($event,ticket)"><i data-v-ui-9200e9d7b7db :class="`priority-${ticket.priority.toLowerCase()}`"></i><span data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ ticket.subject }}</strong><small data-v-ui-9200e9d7b7db>{{ ticket.number }} · {{ requester(ticket) }}</small></span><b data-v-ui-9200e9d7b7db :class="{'overdue':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</b></div><p data-v-ui-9200e9d7b7db v-if="!attentionTickets.length" class="empty">Нет открытых обращений</p></article><article data-v-ui-9200e9d7b7db class="panel crm-surface"><div data-v-ui-9200e9d7b7db class="panel-head"><div data-v-ui-9200e9d7b7db><h2 data-v-ui-9200e9d7b7db>Откуда обращаются</h2></div></div><div data-v-ui-9200e9d7b7db v-for="source in ['EMPLOYEE','B2C','B2B','SYSTEM']" :key="source" class="source-row"><span data-v-ui-9200e9d7b7db>{{ sourceLabels[source] }}</span><b data-v-ui-9200e9d7b7db>{{ tickets.filter(ticket=>ticket.source===source).length }}</b><i data-v-ui-9200e9d7b7db><em data-v-ui-9200e9d7b7db :style="{width:`${tickets.length ? tickets.filter(ticket=>ticket.source===source).length/tickets.length*100 : 0}%`}"></em></i></div></article></section></template>
  <template v-else-if="section === 'tickets'"><section data-v-ui-9200e9d7b7db class="panel ticket-panel crm-surface"><p data-v-ui-9200e9d7b7db v-if="queueFilter" class="queue-label">Очередь: {{ queueFilter }}</p><div data-v-ui-9200e9d7b7db class="filters crm-toolbar"><label class="crm-input-group" data-v-ui-9200e9d7b7db><Search data-v-ui-9200e9d7b7db :size="16" /><input class="crm-input" data-v-ui-9200e9d7b7db v-model="search" placeholder="Номер, тема или заявитель" aria-label="Поиск заявок" /></label><select class="crm-input" data-v-ui-9200e9d7b7db v-model="statusFilter" aria-label="Статус заявки"><option data-v-ui-9200e9d7b7db value="">Все статусы</option><option data-v-ui-9200e9d7b7db v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select><select class="crm-input" data-v-ui-9200e9d7b7db v-model="sourceFilter" aria-label="Источник заявки"><option data-v-ui-9200e9d7b7db value="">Все источники</option><option data-v-ui-9200e9d7b7db v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select><button class="crm-button" data-v-ui-9200e9d7b7db v-if="search||statusFilter||sourceFilter||queueFilter" @click="resetFilters">Сбросить</button></div><p class="hd-result-summary" role="status">Заявок: {{filtered.length}}<template v-if="filtersActive"> из {{tickets.length}}</template></p><div data-v-ui-9200e9d7b7db class="ticket-table"><div data-v-ui-9200e9d7b7db class="ticket-row head crm-table-head"><span data-v-ui-9200e9d7b7db>Заявка</span><span data-v-ui-9200e9d7b7db>Заявитель</span><span data-v-ui-9200e9d7b7db>Источник</span><span data-v-ui-9200e9d7b7db>Приоритет</span><span data-v-ui-9200e9d7b7db>Статус</span><span data-v-ui-9200e9d7b7db>SLA</span></div><div data-v-ui-9200e9d7b7db v-for="ticket in visibleTickets" :key="ticket.id" class="ticket-row crm-table-row" role="button" tabindex="0" @keydown.enter.prevent="openTicket(ticket)" @keydown.space.prevent="openTicket(ticket)" @click="openTicket(ticket)" @contextmenu.prevent="ticketMenu($event,ticket)"><div data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ ticket.subject }}</strong><small data-v-ui-9200e9d7b7db>{{ ticket.number }} · {{ new Date(ticket.createdAt).toLocaleString('ru-RU') }}</small></div><span data-v-ui-9200e9d7b7db class="hd-ticket-cell" data-label="Заявитель">{{ requester(ticket) }}</span><span data-v-ui-9200e9d7b7db class="hd-ticket-cell" data-label="Источник">{{ sourceLabels[ticket.source] }}</span><span data-v-ui-9200e9d7b7db class="hd-ticket-cell" data-label="Приоритет" :class="`text-${ticket.priority.toLowerCase()}`">{{ priorityLabels[ticket.priority] }}</span><span data-v-ui-9200e9d7b7db class="hd-ticket-cell" data-label="Статус">{{ statusLabels[ticket.status] }}</span><span data-v-ui-9200e9d7b7db class="hd-ticket-cell" data-label="Срок" :class="{'red':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</span></div><p data-v-ui-9200e9d7b7db v-if="!filtered.length" class="empty" role="status">{{ filtersActive ? 'По заданным условиям заявок нет. Измените или сбросьте фильтры.' : 'Заявок пока нет. Новые обращения появятся здесь.' }}</p></div><nav v-if="listPages > 1" class="crm-management-pagination" aria-label="Страницы заявок"><span>{{ listPage }} из {{ listPages }} · всего {{ filtered.length }}</span><div><button type="button" class="crm-button" :disabled="listPage <= 1" @click="listPage--">Назад</button><button type="button" class="crm-button" :disabled="listPage >= listPages" @click="listPage++">Далее</button></div></nav></section></template>
  <template v-else-if="section === 'queues'"><section data-v-ui-9200e9d7b7db class="queue-grid"><article data-v-ui-9200e9d7b7db v-for="queue in queues" :key="queue.name"><div data-v-ui-9200e9d7b7db><Users data-v-ui-9200e9d7b7db :size="19" /><span data-v-ui-9200e9d7b7db>{{ queue.name }}</span></div><strong data-v-ui-9200e9d7b7db>{{ queue.open }}</strong><small data-v-ui-9200e9d7b7db>в работе · всего {{ queue.total }}</small><button class="crm-button" data-v-ui-9200e9d7b7db @click="openQueue(queue.name)">Открыть очередь</button></article><article data-v-ui-9200e9d7b7db v-if="!queues.length" class="empty-card">Очереди появятся после первой заявки</article></section></template>
  <template v-else><section data-v-ui-9200e9d7b7db class="knowledge"><div class="crm-surface crm-surface--tint" data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">САМООБСЛУЖИВАНИЕ</p><h2 data-v-ui-9200e9d7b7db>База знаний</h2><span data-v-ui-9200e9d7b7db class="knowledge-status">Скоро</span><p data-v-ui-9200e9d7b7db>Раздел пока недоступен: инструкции и готовые ответы ещё готовятся. Если нужна помощь сейчас, создайте заявку кнопкой «Новая заявка».</p></div><div data-v-ui-9200e9d7b7db class="knowledge-grid"><article class="crm-surface" data-v-ui-9200e9d7b7db><Headphones data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>Рабочие системы</h3><p data-v-ui-9200e9d7b7db>Вход, права доступа и работа внутренних кабинетов.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article><article class="crm-surface" data-v-ui-9200e9d7b7db><MessageSquare data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>Клиентский сервис</h3><p data-v-ui-9200e9d7b7db>Ответы по заказам, оплате, доставке и возвратам.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article><article class="crm-surface" data-v-ui-9200e9d7b7db><CheckCircle2 data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>1С и интеграции</h3><p data-v-ui-9200e9d7b7db>Синхронизация товаров, остатков и каналов продаж.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article></div></section></template>
</div>
<Teleport :disabled="!route.path.startsWith('/crm/')" to="body"><aside data-v-ui-9200e9d7b7db v-if="createOpen && canCreate" class="backdrop admin-dialog-backdrop crm-management-backdrop" @keydown="dialogKeys" @click.self="closeCreate"><form data-v-ui-9200e9d7b7db ref="createPanel" class="drawer create admin-dialog admin-dialog--drawer crm-management-dialog" role="dialog" aria-modal="true" aria-labelledby="support-create-title" @submit.prevent="createTicket"><header data-v-ui-9200e9d7b7db><div data-v-ui-9200e9d7b7db><h2 id="support-create-title" data-v-ui-9200e9d7b7db>Создать заявку</h2></div><button class="crm-button" data-v-ui-9200e9d7b7db type="button" aria-label="Закрыть создание заявки" :disabled="actionBusy" @click="closeCreate"><X data-v-ui-9200e9d7b7db :size="18" /></button></header><div data-v-ui-9200e9d7b7db class="drawer-scroll admin-dialog-body"><p data-v-ui-9200e9d7b7db v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-9200e9d7b7db ui-inline-i-9200e9d7b7db-1 :disabled="actionBusy" ><label data-v-ui-9200e9d7b7db>Тема<input class="crm-input" data-v-ui-9200e9d7b7db v-model="form.subject" required placeholder="Кратко опишите проблему" /></label><label data-v-ui-9200e9d7b7db>Подробное описание<textarea class="crm-input" data-v-ui-9200e9d7b7db v-model="form.description" rows="7" required placeholder="Что произошло и какой результат ожидался" /></label><div data-v-ui-9200e9d7b7db class="two"><label data-v-ui-9200e9d7b7db>Источник<select class="crm-input" data-v-ui-9200e9d7b7db v-model="form.source"><option data-v-ui-9200e9d7b7db v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Приоритет<select class="crm-input" data-v-ui-9200e9d7b7db v-model="form.priority"><option data-v-ui-9200e9d7b7db v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label></div><label data-v-ui-9200e9d7b7db>Затронутый сервис<input class="crm-input" data-v-ui-9200e9d7b7db v-model="form.affectedService" placeholder="Например, 1С или личный кабинет" /></label><div data-v-ui-9200e9d7b7db class="sla-note"><Clock3 data-v-ui-9200e9d7b7db :size="17" /><span data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>SLA будет рассчитан автоматически</strong><small data-v-ui-9200e9d7b7db>По приоритету в календарных часах. Рабочие дни пока не учитываются.</small></span></div></fieldset></div><footer data-v-ui-9200e9d7b7db><button class="crm-button" data-v-ui-9200e9d7b7db type="button" :disabled="actionBusy" @click="closeCreate">Отмена</button><button data-v-ui-9200e9d7b7db class="primary crm-button crm-button--primary" :disabled="actionBusy">{{ actionBusy ? 'Создаём…' : 'Создать заявку' }}</button></footer></form></aside></Teleport>
<Teleport :disabled="!route.path.startsWith('/crm/')" to="body"><aside data-v-ui-9200e9d7b7db v-if="selected" class="backdrop admin-dialog-backdrop crm-management-backdrop" @keydown="dialogKeys" @click.self="closeTicket"><section data-v-ui-9200e9d7b7db ref="detailPanel" class="drawer ticket-detail admin-dialog admin-dialog--drawer crm-management-dialog" role="dialog" aria-modal="true" aria-labelledby="support-detail-title"><header data-v-ui-9200e9d7b7db><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">{{ selected.number }}</p><h2 id="support-detail-title" data-v-ui-9200e9d7b7db>{{ selected.subject }}</h2><span data-v-ui-9200e9d7b7db>{{ sourceLabels[selected.source] }} · {{ requester(selected) }}</span></div><button class="crm-button crm-button--icon" data-v-ui-9200e9d7b7db aria-label="Закрыть заявку" :disabled="actionBusy" @click="closeTicket"><X data-v-ui-9200e9d7b7db :size="18" /></button></header><div data-v-ui-9200e9d7b7db class="drawer-scroll admin-dialog-body"><p data-v-ui-9200e9d7b7db v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-9200e9d7b7db ui-inline-i-9200e9d7b7db-2 class="control-grid" :disabled="actionBusy || !canWriteTicket(selected)" ><label data-v-ui-9200e9d7b7db>Статус<select class="crm-input" data-v-ui-9200e9d7b7db :value="selected.status" @change="changeTicket($event,selected,'status')"><option data-v-ui-9200e9d7b7db v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Приоритет<select class="crm-input" data-v-ui-9200e9d7b7db :value="selected.priority" @change="changeTicket($event,selected,'priority')"><option data-v-ui-9200e9d7b7db v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Исполнитель<select class="crm-input" data-v-ui-9200e9d7b7db :value="selected.assignedToId||''" @change="changeTicket($event,selected,'assignedToId')"><option data-v-ui-9200e9d7b7db value="">Не назначен</option><option data-v-ui-9200e9d7b7db v-for="agent in agents" :key="agent.id" :value="agent.id">{{ [agent.firstName,agent.lastName].filter(Boolean).join(' ')||agent.email }}</option></select></label><label data-v-ui-9200e9d7b7db>Очередь<input class="crm-input" data-v-ui-9200e9d7b7db :value="selected.queue" @change="changeTicket($event,selected,'queue')" /></label></fieldset><p data-v-ui-9200e9d7b7db class="muted">Изменения полей сохраняются сразу. Допустимость действия проверяет сервер.</p><div data-v-ui-9200e9d7b7db class="ticket-actions"><button class="crm-button" data-v-ui-9200e9d7b7db v-if="canWriteTicket(selected) && !['OPEN','RESOLVED','CLOSED'].includes(selected.status)" :disabled="actionBusy" @click="updateTicket(selected,'status','OPEN')">Взять в работу</button><button class="crm-button" data-v-ui-9200e9d7b7db v-if="canWriteTicket(selected) && !['RESOLVED','CLOSED'].includes(selected.status)" :disabled="actionBusy" @click="updateTicket(selected,'status','RESOLVED')">Решить заявку</button><button class="crm-button" data-v-ui-9200e9d7b7db :disabled="actionBusy" @click="copyText(selected.number,'Номер заявки скопирован')">Копировать номер</button></div><section data-v-ui-9200e9d7b7db class="request-text"><h3 data-v-ui-9200e9d7b7db>Описание</h3><p data-v-ui-9200e9d7b7db>{{ selected.description }}</p></section><section data-v-ui-9200e9d7b7db class="comments"><p class="crm-muted">Комментарии сохраняются в CRM. Чтобы отправить ответ клиенту, отметьте «Отправить на email». Для доставки должна быть настроена почта.</p><h3 data-v-ui-9200e9d7b7db>Обсуждение</h3><div data-v-ui-9200e9d7b7db v-for="item in selected.comments" :key="item.id" :class="['comment',{internal:item.isInternal}]"><div data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ [item.author?.firstName,item.author?.lastName].filter(Boolean).join(' ')||item.author?.email||'Заявитель' }}</strong><span data-v-ui-9200e9d7b7db v-if="item.isInternal">Внутренний комментарий</span><span v-if="item.emailDelivery" role="status">{{ deliveryLabel(item.emailDelivery.status) }}</span><small data-v-ui-9200e9d7b7db>{{ new Date(item.createdAt).toLocaleString('ru-RU') }}</small></div><p data-v-ui-9200e9d7b7db>{{ item.body }}</p></div><p data-v-ui-9200e9d7b7db v-if="!selected.comments?.length" class="empty">Комментариев пока нет</p></section></div><footer data-v-ui-9200e9d7b7db class="reply" v-if="canWriteTicket(selected)"><textarea class="crm-input" data-v-ui-9200e9d7b7db v-model="comment" aria-label="Комментарий к заявке" :disabled="actionBusy" rows="2" placeholder="Сохранить комментарий в заявке"></textarea><label class="crm-toggle-row" data-v-ui-9200e9d7b7db><input class="crm-check" data-v-ui-9200e9d7b7db v-model="internalComment" :disabled="actionBusy" type="checkbox" /> Только для сотрудников</label><label class="crm-toggle-row"><input class="crm-check" v-model="sendEmail" :disabled="actionBusy || internalComment || !selected.requesterEmail" type="checkbox" /> Отправить на email: {{ selected.requesterEmail || 'не указан' }}</label><button data-v-ui-9200e9d7b7db class="send crm-button crm-button--primary" aria-label="Сохранить комментарий" :disabled="actionBusy || !comment.trim()" @click="addComment"><Send data-v-ui-9200e9d7b7db :size="16" />{{ actionBusy ? 'Сохраняем…' : 'Сохранить' }}</button></footer></section></aside></Teleport><div data-v-ui-9200e9d7b7db v-if="notice" class="toast">{{ notice }}</div></main></template>
